-- Lernfeld:1 > Das Unternehmen und die eigene Rolle im Betrieb beschreiben > Das Unternehmen > Unternehmensformen > Kapitalgesellschaften > Aktiengesellschaft
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann eine AG von einer Person gegründet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Ein Gründer möglich"}, {"text": "Nein", "correct": false, "because": "AktG erlaubt Einzelgründung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine AG ins Handelsregister eingetragen werden?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht nach AktG"}, {"text": "Nein", "correct": false, "because": "Rechtliche Anforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Haftung in einer AG auf das Gesellschaftsvermögen beschränkt?', 2, '[{"text": "Ja", "correct": true, "because": "AktG §1"}, {"text": "Nein", "correct": false, "because": "Begrenzte Haftungsstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte eine AG im Einzelhandel typisch sein?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel für viele Branchen"}, {"text": "Nein", "correct": false, "because": "Nicht branchenspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Ist die Gründung einer AG kostspielig?', 2, '[{"text": "Ja", "correct": true, "because": "Mindestkapital 50.000 €"}, {"text": "Nein", "correct": false, "because": "Hohe Gründungskosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine AG ohne Mindestkapital gegründet werden?', 2, '[{"text": "Nein", "correct": true, "because": "AktG §7 fordert 50.000 €"}, {"text": "Ja", "correct": false, "because": "Kapitalanforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Vorteil der AG die einfache Kapitalbeschaffung?', 2, '[{"text": "Ja", "correct": true, "because": "Durch Aktien möglich"}, {"text": "Nein", "correct": false, "because": "Klarer Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine AG einen Aufsichtsrat haben?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht ab bestimmter Größe"}, {"text": "Nein", "correct": false, "because": "AktG §95"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil einer AG?', 2, '[{"text": "Begrenzte Haftung", "correct": true, "because": "Nur Gesellschaftsvermögen"}, {"text": "Einfache Gründung", "correct": false, "because": "Nachteil"}, {"text": "Wenig Kapital", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin überlegt eine AG. Was ist ein Nachteil?', 3, '[{"text": "Hohe Gründungskosten", "correct": true, "because": "Mindestkapital nötig"}, {"text": "Begrenzte Haftung", "correct": false, "because": "Vorteil"}, {"text": "Flexibilität", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branche ist für eine AG typisch?', 2, '[{"text": "Industrie", "correct": true, "because": "Große Unternehmen"}, {"text": "Nur Handwerk", "correct": false, "because": "Zu spezifisch"}, {"text": "Nur Dienstleistung", "correct": false, "because": "Nicht beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, wie eine AG gegründet wird. Was sage ich?', 3, '[{"text": "Satzung und Kapital einbringen", "correct": true, "because": "Gründungsprozess"}, {"text": "Nur Vertrag", "correct": false, "because": "Kapital fehlt"}, {"text": "Ohne Eintragung", "correct": false, "because": "Register nötig"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine AG?', 4, '[{"text": "Begrenzte Haftung", "correct": true, "because": "AktG §1"}, {"text": "Kapital durch Aktien", "correct": true, "because": "Finanzierung"}, {"text": "Börsenfähigkeit", "correct": true, "because": "Flexibilität"}, {"text": "Einfache Gründung", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine AG?', 3, '[{"text": "Hohe Gründungskosten", "correct": true, "because": "50.000 € Mindestkapital"}, {"text": "Komplexe Struktur", "correct": true, "because": "Vorstand, Aufsichtsrat"}, {"text": "Hohe Transparenzpflichten", "correct": true, "because": "Berichtspflichten"}, {"text": "Begrenzte Haftung", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Anforderungen gelten für eine AG?', 3, '[{"text": "Mindestkapital 50.000 €", "correct": true, "because": "AktG §7"}, {"text": "Handelsregistereintrag", "correct": true, "because": "Pflicht"}, {"text": "Satzung erstellen", "correct": true, "because": "Grundlage"}, {"text": "Keine Buchführung", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zum Gründungsprozess einer AG?', 4, '[{"text": "Satzung festlegen", "correct": true, "because": "AktG §23"}, {"text": "Kapital einzahlen", "correct": true, "because": "Mindestkapital"}, {"text": "Handelsregistereintrag", "correct": true, "because": "Pflicht"}, {"text": "Keine Gewerbeanmeldung", "correct": false, "because": "Gewerberecht gilt"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine AG hat begrenzte Haftung. b) Sie ist einfach zu gründen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, Gründung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine AG braucht 50.000 € Startkapital. b) Sie ist für kleine Betriebe ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kapital ja, klein nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine AG ist in der Industrie typisch. b) Sie hat keine Transparenzpflichten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Industrie ja, Pflichten ja"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine AG kann Aktien ausgeben. b) Sie braucht keinen Aufsichtsrat.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aktien ja, Aufsichtsrat ab Größe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

